import { PEOPLE } from '../data/people';
import { DOMAINS, TAGS } from '../data/taxonomy';
import type { Lab, LabFounder, Valuation } from '../data/types';

/** "$100B", "$1.45B", "$335M" — no trailing zeros, no unit noise. */
export function money(usdM: number): string {
  if (usdM >= 1000) {
    const b = usdM / 1000;
    const s = b >= 10 ? b.toFixed(0) : b.toFixed(2).replace(/\.?0+$/, '');
    return `$${s}B`;
  }
  return `$${usdM.toFixed(0)}M`;
}

/**
 * Renders the valuation with its qualifier intact. The prefix is load-bearing:
 * ">$1B" and "$1B" describe different states of knowledge.
 */
export function valuationLabel(v: Valuation): string {
  switch (v.qualifier) {
    case 'approx':
      return `~${money(v.usdM)}`;
    case 'gt':
      return `>${money(v.usdM)}`;
    case 'lt':
      return `<${money(v.usdM)}`;
    case 'range':
      return `~${money(v.lowUsdM ?? v.usdM)}–${money(v.highUsdM ?? v.usdM)}`;
    case 'undisclosed':
      return 'Undisclosed';
    default:
      return money(v.usdM);
  }
}

/** A lab-aware label for entities that cannot have a standalone equity value. */
export function labValuationLabel(lab: Lab): string {
  if (lab.structure === 'nonprofit') return 'Not applicable';
  if (lab.structure === 'subsidiary' && lab.valuation.qualifier === 'undisclosed') {
    return 'Not independently valued';
  }
  return valuationLabel(lab.valuation);
}

/** Short human note on how firm the number is, for tooltips and detail panes. */
export function valuationCaveat(lab: Lab): string | null {
  const v = lab.valuation;
  if (lab.structure === 'nonprofit') return 'Nonprofit; equity valuation is not applicable';
  if (lab.structure === 'subsidiary' && v.qualifier === 'undisclosed') {
    return 'Corporate subsidiary; no standalone valuation disclosed';
  }
  if (lab.status === 'public') {
    return v.asOf ? `Market cap as of ${v.asOf} — moves daily` : 'Market cap — moves daily';
  }
  if (v.qualifier === 'undisclosed') return 'Round announced; valuation not disclosed';
  if (v.rumored) return 'Rumored or unconfirmed';
  if (v.qualifier === 'gt') return 'Known only as a lower bound';
  if (v.qualifier === 'lt') return 'Known only as an upper bound';
  if (v.qualifier === 'range') return 'Reported as a range';
  if (v.qualifier === 'approx') return 'Approximate';
  return null;
}

/** The lab's research area, as one line: domain plus any tags. */
export function spaceLabel(lab: Lab): string {
  const domain = DOMAINS[lab.domain].label;
  const tags = (lab.tags ?? []).map((t) => TAGS[t]).join(', ');
  return tags ? `${domain} — ${tags}` : domain;
}

const founderNameCollator = new Intl.Collator('en', { sensitivity: 'base' });

/** Founder records sorted for display by the final segment of each name. */
export function foundersByLastName(lab: Lab): LabFounder[] {
  return [...lab.founders].sort((a, b) => {
    const aName = PEOPLE[a.person].name;
    const bName = PEOPLE[b.person].name;
    const aLast = aName.trim().split(/\s+/).at(-1) ?? aName;
    const bLast = bName.trim().split(/\s+/).at(-1) ?? bName;
    return founderNameCollator.compare(aLast, bLast) || founderNameCollator.compare(aName, bName);
  });
}

export function founderNames(lab: Lab): string {
  return foundersByLastName(lab).map((f) => PEOPLE[f.person].name).join(', ');
}

