/**
 * A third, much shorter tier, for labs whose name still can't be read on a
 * small hex. Only worth an entry where the saving is dramatic — a form that
 * merely trims a word buys no zoom levels and costs the reader the name.
 *
 * These are marks, not abbreviations: at the sizes where they appear there is
 * no room for anything a reader would have to parse. Hover still gives the
 * full name, so nothing is lost that can't be recovered.
 */
const SHORT_NAMES: Record<string, string> = {
  'thinking-machines-lab': 'Thinky',
  'river-ai': 'River',
  ricursive: 'Ricursive',
  'recursive-superintelligence': 'Recursive',
  'ineffable-intelligence': 'Ineffable',
};

/**
 * One drawn element of a mark. Filled when `strokeWidth` is absent, stroked at
 * that width when it's present — a logo built only from filled outlines would
 * have to have its strokes converted to outlines first, which throws away the
 * artwork's own geometry for no gain.
 */
export interface CanvasMarkShape {
  d: string;
  /** In the mark's own coordinate units, so it scales with everything else. */
  strokeWidth?: number;
  /**
   * Round caps where the artwork has them. On a mark drawn from a few thick
   * strokes this is not a detail: butt caps square off every terminal and
   * change the letterform.
   */
  linecap?: 'round';
  /** Preserve rounded corners independently from the stroke's end caps. */
  linejoin?: 'round';
  /**
   * Set where the artwork uses subpaths to carve holes — eyes, counters — out
   * of the shape around them. Those holes let the hexagon's own fill through,
   * which is what makes them read as holes rather than as painted-on shapes.
   */
  fillRule?: 'evenodd';
}

/**
 * A drawn mark, for labs whose short form is a logo rather than letters. Held
 * in its own coordinate box so the canvas can scale it to whatever the hexagon
 * allows; it carries no colour of its own and is drawn in the same ink as the
 * text labels.
 *
 * The box is the artwork's *ink* bounds, not its canvas: the fitter centres on
 * the box, so baked-in padding would make the mark sit small and off-centre.
 */
export interface CanvasMark {
  shapes: CanvasMarkShape[];
  x: number;
  y: number;
  width: number;
  height: number;
  /**
   * Optional override on how much of the hexagon the mark may fill. Line art
   * needs more room than a solid glyph to carry the same weight.
   */
  inset?: number;
  /** Optional canvas-height ceiling for marks that should read a little larger. */
  maxHeight?: number;
}

export type CanvasLabel = string | CanvasMark;

